def is_woodall(n):
    if n <= 0:
        return False
    if n == 1:
        return True
    # Woodall numbers are of the form k * 2^k + 1 where k >= 1
    # We check if (n-1) can be represented as k * 2^k
    val = n - 1
    k = 1
    while True:
        calculated = k * (2 ** k)
        if calculated == val:
            return True
        if calculated > val:
            return False
        k += 1
```

