def is_majority(arr, n, x):
    # Find the first occurrence of x
    left, right = 0, n - 1
    first_occurrence = -1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] != x:
                first_occurrence = mid
                break
            else:
                right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    if first_occurrence == -1:
        return False

    # Check if the element at (first_occurrence + n//2) is x
    # This checks if x appears more than n/2 times
    if first_occurrence + n // 2 < n and arr[first_occurrence + n // 2] == x:
        return True
    else:
        return False
```

