def is_majority(arr, n, x):
    def binary_search_first(arr, low, high, x):
        if high >= low:
            mid = (low + high) // 2
            if mid == 0 or arr[mid-1] != x:
                return mid
            else:
                return binary_search_first(arr, low, mid-1, x)
        return -1

    def binary_search_last(arr, low, high, x):
        if high >= low:
            mid = (low + high) // 2
            if mid == n-1 or arr[mid+1] != x:
                return mid
            else:
                return binary_search_last(arr, mid+1, high, x)
        return -1

    first_idx = binary_search_first(arr, 0, n-1, x)
    if first_idx == -1:
        return False

    last_idx = binary_search_last(arr, first_idx, n-1, x)

    count = last_idx - first_idx + 1
    return count > n // 2
```

