def get_max_sum(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1

    memo = [0] * (n + 1)
    for i in range(n + 1):
        memo[i] = i  # Default case: f(n) = n

    for i in range(2, n + 1):
        # Calculate f(n/2) + f(n/3) + f(n/4) + f(n/5)
        # Using integer division
        val = memo[i // 2] + memo[i // 3] + memo[i // 4] + memo[i // 5]
        memo[i] = max(memo[i], val)

    return memo[n]
```

```python
def get_max_sum(n):
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Memoization dictionary to store computed results
    memo = {0: 0, 1: 1}

    def solve(num):
        if num in memo:
            return memo[num]

        # Calculate the sum of recursive calls
        # Use integer division //
        recursive_sum = solve(num // 2) + solve(num // 3) + solve(num // 4) + solve(num // 5)

        # The result is the maximum of the recursive sum and the number itself
        result = max(recursive_sum, num)
        memo[num] = result
        return result

    return solve(n)
```

