    left = 0
    right = n - 1
    first_pos = -1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            first_pos = mid
            right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    if first_pos == -1:
        return False

    # Check if the element at (first_pos + n/2) is still x
    # Since the array is sorted, if x is a majority, it must occupy the middle index
    # specifically, the element at index (first_pos + n // 2) must be x.
    if first_pos + n // 2 < n:
        return arr[first_pos + n // 2] == x
    else:
        return False

