def is_majority(arr, n, x):
    # Check if the array is actually sorted as required
    # If not, we can't reliably use binary search for majority check on unsorted data
    # given the spec implies a helper for sorted arrays. 
    # For safety in release, if unsorted, return False (or handle as error).
    # Here we return False to prevent false positives on unsorted data.
    if arr != sorted(arr):
        return False

    # Binary search for the first occurrence of x
    def binary_search_first(arr, low, high, x):
        if high >= low:
            mid = (low + high) // 2
            if mid == 0 or arr[mid - 1] != x:
                return mid
            elif arr[mid] == x:
                return binary_search_first(arr, low, mid - 1, x)
            else:
                return binary_search_first(arr, mid + 1, high, x)
        return -1

    first_occurrence = binary_search_first(arr, 0, n - 1, x)

    if first_occurrence == -1:
        return False

    # Check if the element at (first_occurrence + n/2) is still x
    # Majority means count > n/2. If the element at index (start + n/2) is x,
    # then the count from start to that index is > n/2.
    if first_occurrence + n // 2 < n and arr[first_occurrence + n // 2] == x:
        return True

    return False
