def get_max_sum(n):
    if n < 0:
        return 0
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Memoization dictionary to store results
    memo = {0: 0, 1: 1}

    def calc_max_sum(k):
        if k in memo:
            return memo[k]

        # Calculate f(k/2) + f(k/3) + f(k/4) + f(k/5)
        # Use integer division
        sum_recursive = calc_max_sum(k // 2) + calc_max_sum(k // 3) + calc_max_sum(k // 4) + calc_max_sum(k // 5)

        # Store result in memo
        memo[k] = max(k, sum_recursive)
        return memo[k]

    return calc_max_sum(n)
