def is_woodall(n):
    if n <= 0:
        return False
    if n == 1:
        return True

    # Check if n is a power of 2
    if n & (n - 1) != 0:
        return False

    # Check if the next power of 2 is a prime
    # Since n is a power of 2, let m = n * 2. We need to check if m is prime.
    m = n * 2

    # If m is even and greater than 2, it's not prime
    if m > 2 and m % 2 == 0:
        return False

    # Check for primality of m
    i = 3
    while i * i <= m:
        if m % i == 0:
            return False
        i += 2

    return True
