def get_max_sum(n):
    if n == 0:
        return 0
    if n == 1:
        return 1

    # Memoization dictionary to store results of subproblems
    memo = {0: 0, 1: 1}

    def calculate_max_sum(x):
        if x in memo:
            return memo[x]

        # Calculate the sum for n/2, n/3, n/4, n/5
        # Using integer division
        val = calculate_max_sum(x // 2) + calculate_max_sum(x // 3) + calculate_max_sum(x // 4) + calculate_max_sum(x // 5)

        # Store the result in the memo dictionary
        memo[x] = max(x, val)
        return memo[x]

    return calculate_max_sum(n)
