def is_majority(arr, n, x):
    # Find the first occurrence of x
    left = binary_search_first(arr, 0, n-1, x)
    if left == -1:
        return False

    # If first occurrence is at index 'left', the last occurrence is at 'left + n - 1'
    # The count is (last_index - first_index + 1)
    # We need count > n/2
    # last_index = left + count - 1
    # We check if the element at index (left + n//2) is x.
    # If x appears more than n/2 times starting at 'left', it must reach index 'left + n//2'.

    if (left + n//2) < n and arr[left + n//2] == x:
        return True
    return False

def binary_search_first(arr, low, high, x):
    if high >= low:
        mid = (low + high) // 2
        if mid == 0 or x > arr[mid-1] and arr[mid] == x:
            return mid
        elif x > arr[mid]:
            return binary_search_first(arr, mid + 1, high, x)
        else:
            return binary_search_first(arr, low, mid - 1, x)
    return -1
